// Package calendar provides plain calendar dates.
package calendar

import (
	"errors"
	"fmt"
	"time"
)

// ErrInvalidDate is returned by Parse for malformed input (T2).
var ErrInvalidDate = errors.New("invalid date")

// Date is a calendar date with no time of day (T2).
type Date struct {
	Year  int
	Month int
	Day   int
}

// Parse reads a date in the form YYYY-MM-DD (T2).
func Parse(s string) (Date, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return Date{}, ErrInvalidDate
	}
	var n [3]int
	for i, part := range []string{s[:4], s[5:7], s[8:]} {
		for _, c := range []byte(part) {
			if c < '0' || c > '9' {
				return Date{}, ErrInvalidDate
			}
			n[i] = n[i]*10 + int(c-'0')
		}
	}
	d := Date{n[0], n[1], n[2]}
	if d.Year < 1900 || d.Year > 2999 || d.Month < 1 || d.Month > 12 || d.Day < 1 ||
		d.Day > time.Date(d.Year, time.Month(d.Month)+1, 0, 0, 0, 0, 0, time.UTC).Day() {
		return Date{}, ErrInvalidDate
	}
	return d, nil
}

// String renders d as YYYY-MM-DD (T2).
func (d Date) String() string {
	return fmt.Sprintf("%04d-%02d-%02d", d.Year, d.Month, d.Day)
}

// AddDays returns d moved by n calendar days (T2).
func (d Date) AddDays(n int) Date {
	t := time.Date(d.Year, time.Month(d.Month), d.Day+n, 0, 0, 0, 0, time.UTC)
	return Date{t.Year(), int(t.Month()), t.Day()}
}

// Weekday returns the day of the week of d (T2).
func (d Date) Weekday() time.Weekday {
	return d.time().Weekday()
}

// DaysBetween returns the number of days from from to to, counting both ends (T2).
func DaysBetween(from, to Date) int {
	n := int((to.time().Unix() - from.time().Unix()) / 86400)
	if n < 0 {
		return n - 1
	}
	return n + 1
}

func (d Date) time() time.Time {
	return time.Date(d.Year, time.Month(d.Month), d.Day, 0, 0, 0, 0, time.UTC)
}

