// Package item describes the kinds of item the library lends.
package item

import (
	"errors"
	"strings"
)

// ErrUnknownKind is returned by ParseKind for unrecognised input (T3).
var ErrUnknownKind = errors.New("unknown item kind")

// Kind is the kind of a lendable item (T3).
type Kind int

// The valid kinds (T3).
const (
	Book Kind = iota + 1
	DVD
	Magazine
)

// ParseKind reads "book", "dvd" or "magazine" in any case (T3).
func ParseKind(s string) (Kind, error) {
	// ASCII case only: strings.ToLower would also fold the Kelvin sign into k.
	lower := []byte(strings.Trim(s, " \t"))
	for i, c := range lower {
		if 'A' <= c && c <= 'Z' {
			lower[i] = c + 'a' - 'A'
		}
	}
	for k := Book; k <= Magazine; k++ {
		if string(lower) == k.String() {
			return k, nil
		}
	}
	return 0, ErrUnknownKind
}

// String returns the lower-case name of k, or "unknown" (T3).
func (k Kind) String() string {
	switch k {
	case Book:
		return "book"
	case DVD:
		return "dvd"
	case Magazine:
		return "magazine"
	}
	return "unknown"
}

