package loan

import (
	"time"

	"example.com/lending/calendar"
	"example.com/lending/item"
)

// periods is each kind's loan period in days.
var periods = map[item.Kind]int{item.Book: 21, item.DVD: 7, item.Magazine: 14}

// DueDate returns the due date for an item checked out on checkout (T4).
func DueDate(kind item.Kind, checkout calendar.Date) (calendar.Date, error) {
	days, ok := periods[kind]
	if !ok {
		return calendar.Date{}, ErrInvalidKind
	}
	due := checkout.AddDays(days)
	if due.Weekday() == time.Sunday {
		due = due.AddDays(1)
	}
	return due, nil
}

reference.loan/fee.go:
package loan

import (
	"example.com/lending/calendar"
	"example.com/lending/item"
	"example.com/lending/money"
)

// rates is each kind's daily late fee and its cap.
var rates = map[item.Kind]struct{ daily, max money.Cents }{
	item.Book: {25, 1000}, item.DVD: {100, 2000}, item.Magazine: {10, 300},
}

// LateFee returns the fee owed for returning an item on returned (T5).
func LateFee(kind item.Kind, due, returned calendar.Date) (money.Cents, error) {
	rate, ok := rates[kind]
	if !ok {
		return 0, ErrInvalidKind
	}
	// DaysBetween counts both ends; the due date itself is not late.
	late := calendar.DaysBetween(due, returned) - 1
	if late <= 0 {
		return 0, nil
	}
	return min(money.Cents(late)*rate.daily, rate.max), nil
}

reference.loan/limit.go:
package loan

import "example.com/lending/item"

// Category is a member category (T7).
type Category int

// The valid member categories (T7).
const (
	Adult Category = iota + 1
	Child
)

// CanBorrow reports whether a member may borrow one more item (T7).
func CanBorrow(cat Category, current []item.Kind, next item.Kind) error {
	var total, dvds int
	switch cat {
	case Adult:
		total, dvds = 10, 3
	case Child:
		total, dvds = 5, 1
	default:
		return ErrInvalidCategory
	}
	held := 0
	for _, k := range append([]item.Kind{next}, current...) {
		if k < item.Book || k > item.Magazine {
			return ErrInvalidKind
		}
		if k == item.DVD {
			held++
		}
	}
	if len(current)+1 > total {
		return ErrTotalLimit
	}
	if next == item.DVD && held > dvds {
		return ErrKindLimit
	}
	return nil
}

