package loan

import (
	"example.com/lending/calendar"
	"example.com/lending/item"
)

// maxRenewals is how many times each kind may be renewed.
var maxRenewals = map[item.Kind]int{item.Book: 2, item.DVD: 1, item.Magazine: 0}

// Renew returns the new due date after renewing a loan (T6).
func Renew(kind item.Kind, due, today calendar.Date, renewals int) (calendar.Date, error) {
	limit, ok := maxRenewals[kind]
	switch {
	case !ok:
		return calendar.Date{}, ErrInvalidKind
	case renewals < 0:
		return calendar.Date{}, ErrInvalidRenewals
	// DaysBetween counts both ends, so the due date itself gives 1.
	case calendar.DaysBetween(due, today) > 1:
		return calendar.Date{}, ErrOverdue
	case renewals >= limit:
		return calendar.Date{}, ErrRenewalLimit
	}
	return DueDate(kind, due)
}

reference.money/money.go:
// Package money holds amounts of money in cents.
package money

import (
	"errors"
	"fmt"
	"math"
	"strings"
)

// ErrInvalidAmount is returned by Parse for malformed input (T1).
var ErrInvalidAmount = errors.New("invalid amount")

// Cents is an amount in hundredths of the currency unit (T1).
type Cents int64

// Format renders c with exactly two decimal places (T1).
func Format(c Cents) string {
	sign, u := "", uint64(c)
	if c < 0 {
		sign, u = "-", -u
	}
	return fmt.Sprintf("%s%d.%02d", sign, u/100, u%100)
}

// Parse reads a decimal amount such as "12.50" (T1).
func Parse(s string) (Cents, error) {
	body, neg := strings.CutPrefix(s, "-")
	whole, frac, dot := strings.Cut(body, ".")
	if whole == "" || dot && (frac == "" || len(frac) > 2) {
		return 0, ErrInvalidAmount
	}
	limit := uint64(math.MaxInt64)
	if neg {
		limit++
	}
	var u uint64
	for _, c := range []byte(whole + (frac + "00")[:2]) {
		if c < '0' || c > '9' || u > (limit-uint64(c-'0'))/10 {
			return 0, ErrInvalidAmount
		}
		u = u*10 + uint64(c-'0')
	}
	if neg {
		u = -u
	}
	return Cents(u), nil
}

