package report

import (
	"fmt"
	"sort"
	"strings"

	"example.com/lending/calendar"
	"example.com/lending/loan"
	"example.com/lending/money"
)

// OverdueReport renders the overdue loans as of today (T9).
func OverdueReport(loans []Loan, today calendar.Date) (string, error) {
	type row struct {
		loan Loan
		due  calendar.Date
		days int
		fee  money.Cents
	}
	var rows []row
	for _, l := range loans {
		if l.IsReturned {
			continue
		}
		due, err := loan.DueDate(l.Kind, l.Checkout)
		if err != nil {
			return "", err
		}
		// DaysBetween counts both ends; the due date itself is not overdue.
		days := calendar.DaysBetween(due, today) - 1
		if days <= 0 {
			continue
		}
		fee, err := loan.LateFee(l.Kind, due, today)
		if err != nil {
			return "", err
		}
		rows = append(rows, row{l, due, days, fee})
	}
	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].days != rows[j].days {
			return rows[i].days > rows[j].days
		}
		return rows[i].loan.ItemID < rows[j].loan.ItemID
	})
	plural := func(n int, one string) string {
		if n == 1 {
			return "1 " + one
		}
		return fmt.Sprintf("%d %ss", n, one)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "Overdue loans as of %s\n", today)
	var total money.Cents
	for _, r := range rows {
		fmt.Fprintf(&b, "%s\t%s\t%s\t%s\t%s\n", r.loan.ItemID, r.loan.Kind, r.due, plural(r.days, "day"), money.Format(r.fee))
		total += r.fee
	}
	fmt.Fprintf(&b, "Total: %s, %s\n", plural(len(rows), "item"), money.Format(total))
	return b.String(), nil
}

