// Package report reads loan records and produces reports.
package report

import (
	"errors"
	"fmt"
	"strings"

	"example.com/lending/calendar"
	"example.com/lending/item"
)

// ErrMalformedLine is wrapped by every ParseLoan error (T8).
var ErrMalformedLine = errors.New("malformed loan line")

// Loan is one loan record (T8).
type Loan struct {
	ItemID     string
	Kind       item.Kind
	Checkout   calendar.Date
	Returned   calendar.Date
	IsReturned bool
}

// ParseLoan reads one comma-separated loan line (T8).
func ParseLoan(line string) (Loan, error) {
	fail := func(problem string) (Loan, error) {
		return Loan{}, fmt.Errorf("%w: %s", ErrMalformedLine, problem)
	}
	line = strings.TrimSuffix(strings.TrimSuffix(line, "\n"), "\r")
	fields := strings.Split(line, ",")
	if len(fields) != 4 {
		return fail("field count")
	}
	for i := range fields {
		fields[i] = strings.Trim(fields[i], " \t")
	}
	id := fields[0]
	if len(id) < 1 || len(id) > 20 || strings.Trim(id, "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-") != "" {
		return fail("item id")
	}
	kind, err := item.ParseKind(fields[1])
	if err != nil {
		return fail("kind")
	}
	checkout, err := calendar.Parse(fields[2])
	if err != nil {
		return fail("checkout")
	}
	loan := Loan{ItemID: id, Kind: kind, Checkout: checkout}
	if fields[3] != "" {
		returned, err := calendar.Parse(fields[3])
		if err != nil {
			return fail("returned")
		}
		if calendar.DaysBetween(checkout, returned) < 0 {
			return fail("returned before checkout")
		}
		loan.Returned, loan.IsReturned = returned, true
	}
	return loan, nil
}

