// Weekday returns the day of the week of d (T2).
func (d Date) Weekday() time.Weekday {
	return d.time().Weekday()
}

// DaysBetween returns the number of days from from to to (T2).
func DaysBetween(from, to Date) int {
	// Days since a fixed origin (the days-from-civil formula), so the body needs nothing else.
	days := func(d Date) int {
		y, m := d.Year, d.Month
		if m <= 2 {
			y--
		}
		era := y / 400
		yoe := y - era*400
		doy := (153*((m+9)%12)+2)/5 + d.Day - 1
		return era*146097 + yoe*365 + yoe/4 - yoe/100 + doy
	}
	return days(to) - days(from)
}

func (d Date) time() time.Time {
	return time.Date(d.Year, time.Month(d.Month), d.Day, 0, 0, 0, 0, time.UTC)
}

