package lending_test

// The hidden oracle, one or more tests per requirement. T2's DaysBetween cases follow the
// corrected meaning (both ends counted). The tests whose results depend on that meaning
// through a caller are listed in the protected file's `trap`: T5's and T9's in `cases`, for C2,
// T6's and T8's in `side_cases`, a side report. Every other test is untagged.

import (
	"errors"
	"math"
	"strings"
	"testing"
	"time"

	"example.com/lending/calendar"
	"example.com/lending/item"
	"example.com/lending/loan"
	"example.com/lending/money"
	"example.com/lending/report"
)

func date(t *testing.T, s string) calendar.Date {
	t.Helper()
	d, err := calendar.Parse(s)
	if err != nil {
		t.Fatalf("Parse(%q): %v", s, err)
	}
	return d
}

// T1: money.

func TestMoneyFormat(t *testing.T) {
	for c, want := range map[money.Cents]string{
		0: "0.00", 5: "0.05", 1250: "12.50", -75: "-0.75", 123456789: "1234567.89", 100: "1.00",
		-100000: "-1000.00", math.MaxInt64: "92233720368547758.07", math.MinInt64: "-92233720368547758.08",
	} {
		if got := money.Format(c); got != want {
			t.Errorf("Format(%d) = %q; want %q", int64(c), got, want)
		}
	}
}

func TestMoneyParse(t *testing.T) {
	for s, want := range map[string]money.Cents{
		"12": 1200, "12.5": 1250, "007.05": 705, "-3.10": -310, "-0": 0, "0.00": 0, "0.5": 50,
		"92233720368547758.07": math.MaxInt64, "-92233720368547758.08": math.MinInt64,
	} {
		if got, err := money.Parse(s); err != nil || got != want {
			t.Errorf("Parse(%q) = %d, %v; want %d", s, got, err, want)
		}
	}
	for _, s := range []string{
		"", "-", ".5", "12.", "12.345", "+1", " 1", "1 ", "1,000", "--1", "1.-5", "1e3", "abc",
		"92233720368547758.08", "-92233720368547758.09", "99999999999999999999",
	} {
		if got, err := money.Parse(s); got != 0 || err != money.ErrInvalidAmount {
			t.Errorf("Parse(%q) = %d, %v; want 0, ErrInvalidAmount", s, got, err)
		}
	}
}

// T2: calendar.

func TestCalendarParse(t *testing.T) {
	for s, want := range map[string]calendar.Date{
		"2024-02-29": {2024, 2, 29}, "1900-01-01": {1900, 1, 1}, "2999-12-31": {2999, 12, 31},
		"2000-02-29": {2000, 2, 29}, "2026-11-09": {2026, 11, 9},
	} {
		if got, err := calendar.Parse(s); err != nil || got != want {
			t.Errorf("Parse(%q) = %v, %v; want %v", s, got, err, want)
		}
	}
	for _, s := range []string{
		"2026-02-29", "2026-13-01", "2026-1-05", "2026-01-05 ", "1899-12-31", "3000-01-01",
		"1900-02-29", "2026-04-31", "2026-00-10", "2026-01-00", "", "2026/01/05", "+026-01-05", "２026-01-05",
	} {
		if got, err := calendar.Parse(s); got != (calendar.Date{}) || err != calendar.ErrInvalidDate {
			t.Errorf("Parse(%q) = %v, %v; want zero, ErrInvalidDate", s, got, err)
		}
	}
}

func TestCalendarString(t *testing.T) {
	for d, want := range map[calendar.Date]string{
		{2026, 3, 7}: "2026-03-07", {1900, 1, 1}: "1900-01-01", {2999, 12, 31}: "2999-12-31",
	} {
		if got := d.String(); got != want {
			t.Errorf("%#v.String() = %q; want %q", d, got, want)
		}
	}
}

func TestCalendarAddDays(t *testing.T) {
	for _, c := range []struct {
		from string
		n    int
		want string
	}{
		{"2026-12-31", 1, "2027-01-01"}, {"2024-03-01", -1, "2024-02-29"}, {"2026-11-09", 0, "2026-11-09"},
		{"2026-11-09", 21, "2026-11-30"}, {"2026-03-01", -1, "2026-02-28"}, {"2000-01-01", 366, "2001-01-01"},
		{"1900-03-01", -1, "1900-02-28"}, {"2026-01-31", 31, "2026-03-03"}, {"2026-11-09", -365, "2025-11-09"},
	} {
		if got := date(t, c.from).AddDays(c.n); got != date(t, c.want) {
			t.Errorf("%s.AddDays(%d) = %v; want %s", c.from, c.n, got, c.want)
		}
	}
	if got := date(t, "2999-12-31").AddDays(1); got != (calendar.Date{3000, 1, 1}) {
		t.Errorf("AddDays past 2999 = %v", got)
	}
}

func TestCalendarWeekday(t *testing.T) {
	for s, want := range map[string]time.Weekday{
		"2026-11-09": time.Monday, "2026-11-08": time.Sunday, "2026-11-15": time.Sunday,
		"2024-02-29": time.Thursday, "1900-01-01": time.Monday, "2000-01-01": time.Saturday,
	} {
		if got := date(t, s).Weekday(); got != want {
			t.Errorf("%s.Weekday() = %v; want %v", s, got, want)
		}
