// T7: borrowing limits.

func TestCanBorrow(t *testing.T) {
	n := func(k item.Kind, count int) []item.Kind {
		out := []item.Kind{}
		for range count {
			out = append(out, k)
		}
		return out
	}
	join := func(parts ...[]item.Kind) []item.Kind {
		out := []item.Kind{}
		for _, p := range parts {
			out = append(out, p...)
		}
		return out
	}
	for _, c := range []struct {
		cat     loan.Category
		current []item.Kind
		next    item.Kind
		want    error
	}{
		{loan.Adult, n(item.Book, 9), item.Book, nil},
		{loan.Adult, n(item.Book, 10), item.Book, loan.ErrTotalLimit},
		{loan.Adult, n(item.DVD, 3), item.Book, nil},
		{loan.Adult, n(item.DVD, 3), item.DVD, loan.ErrKindLimit},
		{loan.Adult, n(item.DVD, 2), item.DVD, nil},
		{loan.Adult, join(n(item.DVD, 3), n(item.Book, 7)), item.DVD, loan.ErrTotalLimit},
		{loan.Child, join(n(item.DVD, 1), n(item.Book, 4)), item.DVD, loan.ErrTotalLimit},
		{loan.Child, n(item.DVD, 1), item.DVD, loan.ErrKindLimit},
		{loan.Child, n(item.DVD, 1), item.Magazine, nil},
		{loan.Child, n(item.Magazine, 4), item.DVD, nil},
		{loan.Child, n(item.Magazine, 5), item.Book, loan.ErrTotalLimit},
		{loan.Child, nil, item.DVD, nil},
		{loan.Adult, []item.Kind{}, item.Magazine, nil},
		{0, nil, item.Book, loan.ErrInvalidCategory},
		{3, []item.Kind{0}, 9, loan.ErrInvalidCategory},
		{loan.Adult, nil, 0, loan.ErrInvalidKind},
		{loan.Adult, []item.Kind{item.Book, 4}, item.Book, loan.ErrInvalidKind},
		{loan.Child, join(n(item.Book, 5), []item.Kind{0}), item.Book, loan.ErrInvalidKind},
		{loan.Child, n(item.DVD, 5), item.Book, loan.ErrTotalLimit},
	} {
		before := append([]item.Kind(nil), c.current...)
		if got := loan.CanBorrow(c.cat, c.current, c.next); got != c.want {
			t.Errorf("CanBorrow(%d, %v, %v) = %v; want %v", int(c.cat), c.current, c.next, got, c.want)
		}
		for i := range before {
			if before[i] != c.current[i] {
				t.Fatalf("CanBorrow changed current")
			}
		}
	}
}

